from rcb_client import Robot
from gen import cloud
from PIL import Image
import numpy as np
from scipy.ndimage import label
r=Robot();o=r.get_obs(cameras=['top','front','oblique'],include_depth=True)
for c in o.last:Image.fromarray(o.last[c]).save('/app/output/now6_'+c+'.png')
im,P=cloud(o,'top');w=(im.min(2)>170)&(im.max(2).astype(int)-im.min(2)<25)
for ylo in [.03,.06,.09,.12,.15,.18]:
 m=w&(P[:,:,1]>ylo)&(P[:,:,1]<ylo+.03)&(P[:,:,2]>.58)&(P[:,:,2]<.68)&(P[:,:,0]>-.18)&(P[:,:,0]<.1)
 if m.sum():print('hand',ylo,m.sum(),np.round(np.median(P[m],0),3))
for c in ['front','oblique']:
 im,P=cloud(o,c);g=(im.max(2).astype(int)-im.min(2)<15)&(im[:,:,0]<180)&(im[:,:,0]>30);m=g&(P[:,:,2]>.54)&(P[:,:,2]<.6)&(abs(P[:,:,0])<.25)&(P[:,:,1]>-.1)&(P[:,:,1]<.25);lab,n=label(m)
 for i in sorted(range(1,n+1),key=lambda i:(lab==i).sum(),reverse=True)[:2]:
  Q=P[lab==i]
  if len(Q)>10:print('obj',c,len(Q),np.round(np.median(Q,0),3),np.round(Q.min(0),3),np.round(Q.max(0),3))
